<template>
  <Separator v-if="isRender" v-bind="delegatedProps" :class="cn('-mx-1 h-px bg-border', props.class)">
    <slot />
  </Separator>
</template>

<script setup lang="ts">
import type { SeparatorProps } from 'reka-ui';
import type { HTMLAttributes } from 'vue';
import { reactiveOmit } from '@vueuse/core';
import { Separator } from 'reka-ui';
import { computed } from 'vue';
import { cn } from '@/components/ui/utils';
import { useCommand } from '.';

const props = defineProps<SeparatorProps & { class?: HTMLAttributes['class'] }>();

const delegatedProps = reactiveOmit(props, 'class');

const { filterState } = useCommand();
// Matches cmdk semantics: separators are hidden while a search query is active.
const isRender = computed(() => !filterState.search);
</script>
